package alphametics

import (
	"errors"
	"strings"
)

// Solve parses an alphametics puzzle of the form
// "WORD + WORD + ... == WORD" and returns the digit substitution
// that makes the equation valid, or an error if there is none.
func Solve(puzzle string) (map[string]int, error) {
	left, right, ok := strings.Cut(puzzle, "==")
	if !ok {
		return nil, errors.New("alphametics: invalid puzzle, missing \"==\"")
	}
	var words []string
	for _, f := range strings.FieldsFunc(left, func(r rune) bool {
		return r == '+' || r == ' '
	}) {
		if f != "" {
			words = append(words, f)
		}
	}
	right = strings.TrimSpace(right)
	if right == "" {
		return nil, errors.New("alphametics: invalid puzzle, missing result")
	}
	if strings.ContainsAny(right, "+ ") {
		return nil, errors.New("alphametics: right side must be a single word")
	}
	words = append(words, right)

	// Collect letters; leading letters of multi-letter words can't be zero.
	var letters []byte
	for _, w := range words {
		if w == "" {
			return nil, errors.New("alphametics: empty word")
		}
	}
	// Duplicated words are fine, duplicated letters within a single word
	// would make the puzzle unsolvable.
	seen := map[string]bool{}
	for _, w := range words[1:len(words)-1] {
		if seen[w] {
			return nil, errors.New("alphametics: duplicated addend")
		}
		seen[w] = true
	}
	letterIdx := map[byte]int{}
	zeroOK := make([]bool, 0, 16)
	addWord := func(b byte, canBeZero bool) error {
		if _, ok := letterIdx[b]; ok {
			return nil
		}
		if len(letterIdx) >= 10 {
			return errors.New("alphametics: too many letters to assign digits")
		}
		letterIdx[b] = len(letterIdx)
		zeroOK = append(zeroOK, canBeZero)
		return nil
	}
	for n, w := range words {
		isResult := n == len(words)-1
		for k := range []byte(w) {
			leading := k == 0 && len(w) > 1
			if err := addWord(w[k], isResult || !leading); err != nil {
				return nil, err
			}
		}
	}

	// slots is the flat list of letter indexes per column; addCols holds
	// the ranges of addend letters for each column.
	colSlots := make([][]int, 0, 16)
	colAddLen := make([]int, 0, 16)
	maxLen := 0
	for _, w := range words {
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}
	for col := 0; col < maxLen; col++ {
		var slots []int
		addCount := 0
		used := map[int]bool{}
		for n, w := range words {
			isResult := n == len(words)-1
			k := len(w) - 1 - col
			if k < 0 {
				continue
			}
			idx := letterIdx[w[k]]
			if _, dup := used[idx]; dup {
				return nil, errors.New("alphametics: duplicated letter in column")
			}
			used[idx] = true
			slots = append(slots, idx)
			if !isResult {
				addCount++
			}
		}
		colSlots = append(colSlots, slots)
		colAddLen = append(colAddLen, addCount)
	}
	// The last column must contain at least one addend letter,
	// otherwise the equation has no solution.
	last := colSlots[len(colSlots)-1]
	if colAddLen[len(colSlots)-1] == 0 {
		return nil, errors.New("alphametics: no solution possible")
	}

	// Build the ordered list of positions to assign. For every column
	// except the last, exactly one unassigned slot (the result letter, or
	// an addend letter when the result letter is already known) is
	// assigned last so that the column can be validated. The last column's
	// free slots are appended in order, then the target slot (encoded
	// negative) closes the list and forces the total to vanish.
	var pos []int32
	assigned := make([]bool, len(letterIdx))
	for n := 0; n < len(colSlots)-1; n++ {
		slots := colSlots[n]
		var free []int
		for _, s := range slots {
			if !assigned[s] {
				free = append(free, s)
			}
		}
		target := -1
		for _, s := range free {
			if n >= len(colAddLen) || colAddLen[n] == len(slots) {
				// every slot in this column is an addend slot
				target = s
			} else {
				// check whether s is the result slot: index > addend count
				// is not reliable (result may be shorter); test membership.
				if !isAddendSlot(n, s, slots, colAddLen) {
					target = s
					break
				}
			}
		}
		if target < 0 {
			target = free[len(free)-1]
		}
		for _, s := range free {
			if s != target {
				pos = append(pos, int32(s))
				assigned[s] = true
			}
		}
		pos = append(pos, int32(target)|maskNeg)
		assigned[target] = true
	}
	var lastFree []int
	for _, s := range last {
		if !assigned[s] {
			lastFree = append(lastFree, s)
		}
	}
	for _, s := range lastFree {
		pos = append(pos, int32(s))
	}
	pos = append(pos, int32(last[0])|maskNeg)

	s := &solver{
		zeroOK: zeroOK,
		pos:    pos,
		colAdd: make([][]int32, len(colSlots)),
		colRes: make([]int32, len(colSlots)),
	}
	for n, slots := range colSlots {
		var add []int32
		for k, sl := range slots {
			if k < colAddLen[n] || isResultSlot(n, sl, words) {
				if k < colAddLen[n] {
					add = append(add, int32(sl))
				}
			}
		}
		s.colAdd[n] = add
		if len(slots)-1 >= 0 {
			// result slot of this column, if any; -1 when the column has
			// no result letter.
			s.colRes[n] = -1
			for _, sl := range slots {
				if !isAddendIdx(n, sl, words) {
					s.colRes[n] = int32(sl)
				}
			}
		}
	}

	res := make([]int, len(letterIdx))
	if s.solve(0, 0, 0, 0, res) {
		out := make(map[string]int, len(letterIdx))
		for b, i := range letterIdx {
			out[string(rune(b))] = res[i]
		}
		return out, nil
	}
	return nil, errors.New("alphametics: no solution")
}

const maskNeg = int32(1 << 20)

// isAddendSlot reports whether the slot is one of the addend letters of
// the column. The addend letters are exactly those that also appear in
// addend words of that column; since addend slots come before the result
// slot only for the result word, membership is decided by the word
// structure passed via helpers below.
func isAddendSlot(col, slot int, slots []int, colAddLen []int) bool {
	_ = col
	_ = slots
	_ = colAddLen
	return true
}

type solver struct {
	zeroOK []bool
	pos    []int32
	colAdd [][]int32
	colRes []int32
}

func (s *solver) solve(i, mask, mod, total int, res []int) bool {
	p := s.pos[i]
	neg := p&maskNeg != 0
	l := int(p & ^maskNeg)
	if neg {
		if mod != 0 {
			return false
		}
		if i == 0 {
			return total == 0
		}
		return s.solve(i-1, mask, (mod*10+total/10)%10, total/10, res)
	}
	lo := 0
	if !s.zeroOK[l] {
		lo = 1
	}
	for d := 9; d >= lo; d-- {
		if mask&(1<<d) != 0 {
			continue
		}
		res[l] = d
		m := mod
		if i < len(s.colAdd) {
			for _, a := range s.colAdd[i] {
				m += res[a]
			}
			if r := s.colRes[i]; r >= 0 {
				m -= res[r]
			}
		}
		m *= 10
		if s.solve(i-1, mask|(1<<d), m%10, m/10, res) {
			return true
		}
	}
	res[l] = 0
	return false
}

// Helpers kept minimal: determine, per column, whether a slot belongs to
// the result word using the original words.
var (
	globalAdd   [][]int32
	globalIsRes []bool
)

func isResultSlot(col, slot int, words []string) bool {
	_ = col
	_ = slot
	_ = words
	return false
}

func isAddendIdx(col, slot int, words []string) bool {
	_ = col
	_ = slot
	_ = words
	return true
}

package alphametics

import (
	"errors"
	"strings"
)

const maskNeg = int32(1 << 20)

// Solve parses an alphametics puzzle of the form
// "WORD + WORD + ... == WORD" and returns the digit substitution
// that makes the equation valid, or an error if there is none.
func Solve(puzzle string) (map[string]int, error) {
	left, right, ok := strings.Cut(puzzle, "==")
	if !ok {
		return nil, errors.New("alphametics: invalid puzzle, missing \"==\"")
	}
	right = strings.TrimSpace(right)
	if right == "" || strings.ContainsAny(right, "+ ") {
		return nil, errors.New("alphametics: right side must be a single word")
	}
	var addends []string
	for _, f := range strings.FieldsFunc(left, func(r rune) bool {
		return r == '+' || r == ' '
	}) {
		if f != "" {
			addends = append(addends, f)
		}
	}
	if len(addends) == 0 {
		return nil, errors.New("alphametics: no addends")
	}
	words := append(append([]string{}, addends...), right)

	// Collect letters; the leading letter of a multi-letter word may not
	// be zero.
	letterIdx := map[byte]int{}
	zeroOK := make([]bool, 0, 16)
	for n, w := range words {
		isResult := n == len(words)-1
		for k := 0; k < len(w); k++ {
			b := w[k]
			if _, ok := letterIdx[b]; ok {
				continue
			}
			if len(letterIdx) >= 10 {
				return nil, errors.New("alphametics: too many different letters")
			}
			letterIdx[b] = len(letterIdx)
			zeroOK = append(zeroOK, isResult || k > 0)
		}
	}

	// Group letters by decimal column (0 = units). Letters of the result
	// word are marked with a negative value.
	maxLen := 0
	for _, w := range words {
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}
	colAdds := make([][]int, maxLen)
	colRes := make([]int, maxLen)
	for i := range colRes {
		colRes[i] = -1
	}
	for n, w := range words {
		isResult := n == len(words)-1
		for k := 0; k < len(w); k++ {
			col := len(w) - 1 - k
			li := letterIdx[w[k]]
			leading := k == 0 && len(w) > 1
			_ = leading
			if isResult {
				// place in column; encode with negative marker later
				if colRes[col] < 0 {
					colRes[col] = li
				} else if colRes[col] != li {
					return nil, errors.New("alphametics: two result letters in one column")
				}
			} else {
				colAdds[col] = append(colAdds[col], li)
			}
		}
	}
	// Every column of the result must be reachable: a column containing a
	// result letter but no addend letter above it makes the puzzle
	// unsolvable (the extra result digit can never be produced).
	for col := maxLen - 1; col >= 0; col-- {
		if colRes[col] >= 0 && col > 0 && len(colAdds[col]) == 0 {
			// remaining higher columns are also checkable via the same rule
			return nil, errors.New("alphametics: no solution possible")
		}
	}

	s := &solver{zeroOK: zeroOK}

	// Order the columns; for every column except the last, exactly one
	// not-yet-encountered slot is deferred so that the column constraint
	// can be checked as soon as it is assigned. The last column is closed
	// out by a synthetic target position.
	seen := make([]bool, len(letterIdx))
	var pos []int32
	checkCol := make([]bool, maxLen) // columns whose constraint is checked at their target
	for col := 0; col < maxLen-1; col++ {
		var slots []int
		for _, a := range colAdds[col] {
			slots = append(slots, a)
		}
		if colRes[col] >= 0 {
			slots = append(slots, colRes[col])
		}
		var free []int
		for _, sl := range slots {
			if !seen[sl] {
				free = append(free, sl)
			}
		}
		target := -1
		if colRes[col] >= 0 && !seen[colRes[col]] {
			target = colRes[col]
		} else if len(free) > 0 {
			target = free[0]
		}
		for _, sl := range free {
			if sl != target {
				pos = append(pos, int32(sl))
				seen[sl] = true
			}
		}
		if target >= 0 {
			pos = append(pos, int32(target)|maskNeg)
			seen[target] = true
			checkCol[col] = true
		} else if colRes[col] >= 0 {
			// all slots of this column were already assigned earlier;
			// the constraint still has to be enforced once.
			pos = append(pos, maskNeg)
			checkCol[col] = true
		}
	}
	// Last column: assign its free slots in order...
	lastCol := maxLen - 1
	for _, a := range colAdds[lastCol] {
		if !seen[a] {
			pos = append(pos, int32(a))
			seen[a] = true
		}
	}
	if r := colRes[lastCol]; r >= 0 && !seen[r] {
		pos = append(pos, int32(r))
		seen[r] = true
	}
	// ...then close it with the final target, which also verifies the
	// accumulated total.
	pos = append(pos, maskNeg)

	// Precompute per-column contributions.
	s.colAdds = make([][]int32, maxLen)
	s.colRes = make([]int32, maxLen)
	s.check = make([]bool, maxLen)
	for col := 0; col < maxLen; col++ {
		for _, a := range colAdds[col] {
			s.colAdds[col] = append(s.colAdds[col], int32(a))
		}
		s.colRes[col] = int32(colRes[col])
		s.check[col] = checkCol[col] || col == lastCol
	}

	res := make([]int, len(letterIdx))
	if s.solve(len(pos)-1, 0, 0, 0, res) {
		out := make(map[string]int, len(letterIdx))
		for b, i := range letterIdx {
			out[string(rune(b))] = res[i]
		}
		return out, nil
	}
	return nil, errors.New("alphametics: no solution")
}

type solver struct {
	zeroOK []bool
	pos    []int32
	colAdds [][]int32
	colRes  []int32
	check   []bool
}

// solve walks the position list backwards. mod and total carry the
// partial column sums of the columns not yet completely processed.
func (s *solver) solve(i int, mask, mod, total int, res []int) bool {
	p := s.pos[i]
	if p&maskNeg != 0 {
		if mod != 0 {
			return false
		}
		if i == 0 {
			return total == 0
		}
		return s.solve(i-1, mask, (total/10)%10, total/10, res)
	}
	l := int(p & ^maskNeg)
	lo := 0
	if !s.zeroOK[l] {
		lo = 1
	}
	for d := 9; d >= lo; d-- {
		if mask&(1<<d) != 0 {
			continue
		}
		res[l] = d
		if s.solve(i-1, mask|(1<<d), mod, total, res) {
			return true
		}
	}
	res[l] = 0
	return false
}

package alphametics

import (
	"errors"
	"strings"
)

const maskNeg = int32(1 << 20)

// Solve parses an alphametics puzzle of the form
// "WORD + WORD + ... == WORD" and returns the digit substitution
// that makes the equation valid, or an error if there is none.
func Solve(puzzle string) (map[string]int, error) {
	left, right, ok := strings.Cut(puzzle, "==")
	if !ok {
		return nil, errors.New("alphametics: invalid puzzle, missing \"==\"")
	}
	right = strings.TrimSpace(right)
	if right == "" || strings.ContainsAny(right, "+ ") {
		return nil, errors.New("alphametics: right side must be a single word")
	}
	var addends []string
	for _, f := range strings.FieldsFunc(left, func(r rune) bool {
		return r == '+' || r == ' '
	}) {
		if f != "" {
			addends = append(addends, f)
		}
	}
	if len(addends) == 0 {
		return nil, errors.New("alphametics: no addends")
	}
	words := append(append([]string{}, addends...), right)

	// Collect letters; the leading letter of a multi-letter word may not
	// be zero.
	letterIdx := map[byte]int{}
	zeroOK := make([]bool, 0, 16)
	for n, w := range words {
		isResult := n == len(words)-1
		for k := 0; k < len(w); k++ {
			b := w[k]
			if _, ok := letterIdx[b]; ok {
				continue
			}
			if len(letterIdx) >= 10 {
				return nil, errors.New("alphametics: too many different letters")
			}
			letterIdx[b] = len(letterIdx)
			zeroOK = append(zeroOK, isResult || k > 0)
		}
	}

	maxLen := 0
	for _, w := range words {
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}

	// Group letter indexes per decimal column (0 = units).
	colAdds := make([][]int, maxLen)
	colRes := make([]int, maxLen)
	for i := range colRes {
		colRes[i] = -1
	}
	for n, w := range words {
		isResult := n == len(words)-1
		for k := 0; k < len(w); k++ {
			col := len(w) - 1 - k
			li := letterIdx[w[k]]
			if isResult {
				if colRes[col] < 0 {
					colRes[col] = li
				} else if colRes[col] != li {
					return nil, errors.New("alphametics: two result letters in one column")
				}
			} else {
				colAdds[col] = append(colAdds[col], li)
			}
		}
	}
	// A column above every addend that carries a result letter can never
	// be produced by the sum.
	for col := 1; col < maxLen; col++ {
		if colRes[col] >= 0 {
			hasAddends := false
			for c := 0; c < col; c++ {
				if len(colAdds[c]) > 0 {
					hasAddends = true
					break
				}
				if len(colAdds[c]) > 0 {
					break
				}
			}
			if !hasAddends && len(colAdds[col]) == 0 {
				return nil, errors.New("alphametics: no solution possible")
			}
			break
		}
	}

	// Build the ordered list of positions to assign, processed back-to-front
	// during the search. For each column except the last, every new letter
	// except one (the deferred "target") is assigned as a plain slot; the
	// target is encoded negative, which marks a point where the whole
	// column has just become known and its constraint can be checked. The
	// final column is closed with a negative target holding no letter.
	seen := make([]bool, len(letterIdx))
	var pos []int32
	for col := 0; col < maxLen-1; col++ {
		var slots []int
		for _, a := range colAdds[col] {
			slots = append(slots, a)
		}
		if colRes[col] >= 0 {
			slots = append(slots, colRes[col])
		}
		var free []int
		for _, sl := range slots {
			if !seen[sl] {
				free = append(free, sl)
			}
		}
		target := -1
		if r := colRes[col]; r >= 0 && !seen[r] {
			target = r
		} else if len(free) > 0 {
			target = free[0]
		}
		for _, sl := range free {
			if sl != target {
				pos = append(pos, int32(sl))
				seen[sl] = true
			}
		}
		if target >= 0 {
			pos = append(pos, int32(target)|maskNeg)
			seen[target] = true
		} else {
			// Whole column was already assigned; add a pure check point.
			pos = append(pos, maskNeg)
		}
	}
	lastCol := maxLen - 1
	for _, a := range colAdds[lastCol] {
		if !seen[a] {
			pos = append(pos, int32(a))
			seen[a] = true
		}
	}
	if r := colRes[lastCol]; r >= 0 && !seen[r] {
		pos = append(pos, int32(r))
		seen[r] = true
	}
	pos = append(pos, maskNeg) // final check: total must be zero

	s := &solver{
		zeroOK:  zeroOK,
		pos:     pos,
		colAdds: make([][]int32, maxLen),
		colRes:  make([]int32, maxLen),
	}
	for col := 0; col < maxLen; col++ {
		for _, a := range colAdds[col] {
			s.colAdds[col] = append(s.colAdds[col], int32(a))
		}
		s.colRes[col] = int32(colRes[col])
	}

	res := make([]int, len(letterIdx))
	if s.solve(len(pos)-1, 0, 0, res) {
		out := make(map[string]int, len(letterIdx))
		for b, i := range letterIdx {
			out[string(rune(b))] = res[i]
		}
		return out, nil
	}
	return nil, errors.New("alphametics: no solution")
}

type solver struct {
	zeroOK  []bool
	pos     []int32
	colAdds [][]int32
	colRes  []int32
}

// solve walks the position list from the last (top) column down. total
// holds the already-computed sum of the columns strictly above the one
// being processed; the target positions verify that the running sum is
// divisible by the proper power of ten and pass the carry downwards.
func (s *solver) solve(i int, mask, total int, res []int) bool {
	p := s.pos[i]
	if p&maskNeg != 0 {
		// Determine which column this check closes: count targets
		// from the start of the list up to and including i... but it is
		// easier to derive it while recursing; see helper below.
		return s.checkAndGo(i, mask, total, res)
	}
	l := int(p & ^maskNeg)
	lo := 0
	if !s.zeroOK[l] {
		lo = 1
	}
	for d := 9; d >= lo; d-- {
		if mask&(1<<d) != 0 {
			continue
		}
		res[l] = d
		if s.solve(i-1, mask|(1<<d), total, res) {
			return true
		}
	}
	res[l] = 0
	return false
}

// colOfTarget returns the column index closed by the target position i
// (targets appear in order from column 0 upward; the final one closes
// column maxLen-1).
func (s *solver) colOfTarget(i int) int {
	t := 0
	for j := 0; j <= i; j++ {
		if s.pos[j]&maskNeg != 0 {
			if j == i {
				return t
			}
			t++
		}
	}
	return -1
}

// targetsUpTo returns the number of target positions in pos[0..i].
func (s *solver) targetsUpTo(i int) int {
	t := 0
	for j := 0; j <= i; j++ {
		if s.pos[j]&maskNeg != 0 {
			t++
		}
	}
	return t
}

func (s *solver) checkAndGo(i, mask, total int, res []int) bool {
	col := s.targetsUpTo(i) - 1 // this target closes column col
	// Sum of column col using the assignment in res.
	sum := total
	for _, a := range s.colAdds[col] {
		sum += res[a]
	}
	if r := s.colRes[col]; r >= 0 {
		sum -= res[r]
	}
	_ = col
	// For the final target (col == number of columns - 1) require sum == 0,
	// otherwise the divisibility check on the next lower column applies
	// through the recursion below.
	if i == 0 {
		return sum == 0
	}
	// Columns are processed top-down: the target at column col receives
	// the sum of columns above; here we only verify locally that
	// (sum of column col) combined with higher columns leaves a carry
	// usable by column col-1. Because the ordering guarantees that the
	// check happens as soon as the column is complete, sum itself must be
	// divisible by 10 when a lower column exists.
	if sum%10 != 0 {
		return false
	}
	return s.solve(i-1, mask, sum/10, res)
}

package alphametics

import (
	"errors"
	"strings"
)

const maskNeg = int32(1 << 20)

// Solve parses an alphametics puzzle of the form
// "WORD + WORD + ... == WORD" and returns the digit substitution
// that makes the equation valid, or an error if there is none.
func Solve(puzzle string) (map[string]int, error) {
	left, right, ok := strings.Cut(puzzle, "==")
	if !ok {
		return nil, errors.New("alphametics: invalid puzzle, missing \"==\"")
	}
	right = strings.TrimSpace(right)
	if right == "" || strings.ContainsAny(right, "+ ") {
		return nil, errors.New("alphametics: right side must be a single word")
	}
	var addends []string
	for _, f := range strings.FieldsFunc(left, func(r rune) bool {
		return r == '+' || r == ' '
	}) {
		if f != "" {
			addends = append(addends, f)
		}
	}
	if len(addends) == 0 {
		return nil, errors.New("alphametics: no addends")
	}
	words := append(append([]string{}, addends...), right)

	maxAddLen := 0
	for _, w := range addends {
		if len(w) > maxAddLen {
			maxAddLen = len(w)
		}
	}
	if len(right) > maxAddLen+1 {
		return nil, errors.New("alphametics: no solution possible")
	}

	// Collect letters; the leading letter of a multi-letter word may not
	// be zero.
	letterIdx := map[byte]int{}
	zeroOK := make([]bool, 0, 16)
	for n, w := range words {
		isResult := n == len(words)-1
		for k := 0; k < len(w); k++ {
			b := w[k]
			if _, ok := letterIdx[b]; ok {
				continue
			}
			if len(letterIdx) >= 10 {
				return nil, errors.New("alphametics: too many different letters")
			}
			letterIdx[b] = len(letterIdx)
			zeroOK = append(zeroOK, isResult || k > 0)
		}
	}

	// Group letter indexes per decimal column (0 = units).
	maxLen := 0
	for _, w := range words {
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}
	colAdds := make([][]int, maxLen)
	colRes := make([]int, maxLen)
	for i := range colRes {
		colRes[i] = -1
	}
	for n, w := range words {
		isResult := n == len(words)-1
		for k := 0; k < len(w); k++ {
			col := len(w) - 1 - k
			li := letterIdx[w[k]]
			if isResult {
				if colRes[col] < 0 {
					colRes[col] = li
				} else if colRes[col] != li {
					return nil, errors.New("alphametics: duplicated letter in column")
				}
			} else {
				colAdds[col] = append(colAdds[col], li)
			}
		}
	}

	// Build the ordered list of positions, processed back-to-front by the
	// search. For each column except the last, all newly appearing letters
	// are assigned as plain positions except one deferred "target", which
	// is encoded negative: when the search reaches a target, the whole
	// column is known and its constraint is verified there. Columns whose
	// letters all appeared earlier still emit a (letterless) target so the
	// column constraint is never skipped. The list ends with the final
	// target closing the last column.
	seen := make([]bool, len(letterIdx))
	var pos []int32
	// Per target: the column it closes and, for the initial (top) target,
	// the exponent of ten the running sum must be divisible by.
	type targetInfo struct {
		col int
		exp int // -1 for the final target (require total == 0)
	}
	var targets []targetInfo

	for col := 0; col < maxLen-1; col++ {
		var slots []int
		for _, a := range colAdds[col] {
			slots = append(slots, a)
		}
		if colRes[col] >= 0 {
			slots = append(slots, colRes[col])
		}
		var free []int
		for _, sl := range slots {
			if !seen[sl] {
				free = append(free, sl)
			}
		}
		target := -1
		if r := colRes[col]; r >= 0 && !seen[r] {
			target = r
		} else if len(free) > 0 {
			target = free[0]
		}
		for _, sl := range free {
			if sl != target {
				pos = append(pos, int32(sl))
				seen[sl] = true
			}
		}
		if target >= 0 {
			pos = append(pos, int32(target)|maskNeg)
			seen[target] = true
		} else {
			pos = append(pos, maskNeg)
		}
		targets = append(targets, targetInfo{col: col, exp: maxLen - 1 - col})
	}
	// Final column: assign all its remaining letters, then close with the
	// final target.
	lastCol := maxLen - 1
	for _, a := range colAdds[lastCol] {
		if !seen[a] {
			pos = append(pos, int32(a))
			seen[a] = true
		}
	}
	if r := colRes[lastCol]; r >= 0 && !seen[r] {
		pos = append(pos, int32(r))
		seen[r] = true
	}
	pos = append(pos, maskNeg)
	// The topmost target (processed first) must check divisibility of the
	// entire number by 10^(maxLen-1); subsequent targets only by 10.
	// Targets are stored bottom-up; the search starts from the top, i.e.
	// the last stored, and the exponent of each target below the top is 1.
	for i := range targets {
		targets[i].exp = 1
	}
	if len(targets) > 0 {
		targets[len(targets)-1].exp = maxLen - 1
	} else {
		targets = append(targets, targetInfo{})
	}

	s := &solver{
		zeroOK:  zeroOK,
		pos:     pos,
		colAdds: make([][]int32, maxLen),
		colRes:  make([]int32, maxLen),
		targets: targets,
	}
	for col := 0; col < maxLen; col++ {
		for _, a := range colAdds[col] {
			s.colAdds[col] = append(s.colAdds[col], int32(a))
		}
		s.colRes[col] = int32(colRes[col])
	}

	res := make([]int, len(letterIdx))
	if s.solve(len(pos)-1, len(s.targets)-1, 0, 0, res) {
		out := make(map[string]int, len(letterIdx))
		for b, i := range letterIdx {
			out[string(rune(b))] = res[i]
		}
		return out, nil
	}
	return nil, errors.New("alphametics: no solution")
}

type solver struct {
	zeroOK  []bool
	pos     []int32
	colAdds [][]int32
	colRes  []int32
	targets []targetInfo
}

// solve walks the position list from the end to the start. ti is the
// index of the next target (also walked from the end) and total is the
// running sum contributed by the columns processed so far.
func (s *solver) solve(i int, ti int, mod, total int, res []int) bool {
	p := s.pos[i]
	if p&maskNeg == 0 {
		l := int(p)
		lo := 0
		if !s.zeroOK[l] {
			lo = 1
		}
		for d := 9; d >= lo; d-- {
			if mod&(1<<d) != 0 {
				continue
			}
			res[l] = d
			if s.solve(i-1, ti, mod|(1<<d), total, res) {
				return true
			}
		}
		res[l] = 0
		return false
	}

	// Target position: verify the column it closes.
	t := s.targets[ti]
	sum := total
	for _, a := range s.colAdds[t.col] {
		sum += res[a]
	}
	if r := s.colRes[t.col]; r >= 0 {
		sum -= res[r]
	}
	if t.exp < 0 {
		return sum == 0
	}
	div := 1
	for e := 0; e < t.exp; e++ {
		div *= 10
	}
	if sum%div != 0 {
		return false
	}
	return s.solve(i-1, ti-1, mod, sum/div, res)
}

