	maxLen := 0
	for _, w := range words {
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}
	colAdds := make([][]int, maxLen)
	colRes := make([]int, maxLen)
	for i := range colRes {
		colRes[i] = -1
	}
