				}
			} else {
				colAdds[col] = append(colAdds[col], li)
			}
		}
	}

	// Build the ordered list of positions, processed back-to-front by the
	// search. Positions are encoded as follows:
	//   >= 1:  assign digit to letter (value-1)
	//   <= -1: target -1-(t): the column closed by target t is complete;
	//          verify its constraint and propagate the carry.
	//
	// For every column except the last, all newly appearing letters are
	// assigned as plain positions except one deferred letter (the target);
	// when that target is reached the whole column is known and can be
	// checked. Columns whose letters all appeared earlier emit a
	// letterless target so their constraint is never skipped. The list
	// ends with the target closing the last column.
	seen := make([]bool, len(letterIdx))
	var pos []int
	type targetInfo struct {
		col int
		exp int // power of ten the running sum must be divisible by
	}
	var targets []targetInfo

	for col := 0; col < maxLen-1; col++ {
		var slots []int
		for _, a := range colAdds[col] {
			slots = append(slots, a)
		}
		if colRes[col] >= 0 {
			slots = append(slots, colRes[col])
		}
		var free []int
		for _, sl := range slots {
			if !seen[sl] {
				free = append(free, sl)
			}
		}
		target := -1
		if r := colRes[col]; r >= 0 && !seen[r] {
			target = r
		} else if len(free) > 0 {
			target = free[0]
		}
		for _, sl := range free {
			if sl != target {
				pos = append(pos, sl+1)
				seen[sl] = true
			}
		}
		if target >= 0 {
			seen[target] = true
		}
		// Topmost target (col == maxLen-2) must clear the whole number:
		// its exponent is maxLen-1; lower ones only divide by 10.
		exp := 1
		if col == maxLen-2 {
			exp = maxLen - 1
		}
		_ = exp
		if col == maxLen-2 {
			targets = append(targets, targetInfo{col: col, exp: maxLen - 1})
		} else {
			targets = append(targets, targetInfo{col: col, exp: 1})
		}
		pos = append(pos, -1-len(targets))
		if target < 0 {
			// letterless target; nothing else to do
		}
	}
	// Final column: assign all its remaining letters, then close with a
	// target that requires the accumulated total to be exactly zero.
	lastCol := maxLen - 1
	for _, a := range colAdds[lastCol] {
		if !seen[a] {
			pos = append(pos, a+1)
			seen[a] = true
		}
	}
	if r := colRes[lastCol]; r >= 0 && !seen[r] {
		pos = append(pos, r+1)
		seen[r] = true
	}
	if maxLen == 1 {
		// The single column is both the top and the last one.
		targets = append(targets, targetInfo{col: 0, exp: -1})
		pos = append(pos, -1-len(targets))
	} else {
		targets = append(targets, targetInfo{col: lastCol, exp: -1})
		pos = append(pos, -1-len(targets))
	}

	s := &solver{
		zeroOK:  zeroOK,
		pos:     pos,
		colAdds: make([][]int32, maxLen),
		colRes:  make([]int32, maxLen),
		targets: targets,
	}
	for col := 0; col < maxLen; col++ {
		for _, a := range colAdds[col] {
			s.colAdds[col] = append(s.colAdds[col], int32(a))
		}
		s.colRes[col] = int32(colRes[col])
	}

	res := make([]int, len(letterIdx))
	if s.solve(len(pos)-1, 0, res) {
		out := make(map[string]int, len(letterIdx))
		for b, i := range letterIdx {
			out[string(rune(b))] = res[i]
		}
		return out, nil
	}
	return nil, errors.New("alphametics: no solution")
}

type targetInfo struct {
	col int
	exp int // -1 means "total must be exactly zero"
}

type solver struct {
	zeroOK  []bool
	pos     []int
	colAdds [][]int32
	colRes  []int32
	targets []targetInfo
}

// solve walks the position list from its end to its start. total holds
// the running value of the columns processed so far; at each target the
// column it closes is verified and the carry is propagated down.
func (s *solver) solve(i int, total int, res []int) bool {
	p := s.pos[i]
	if p > 0 {
		l := p - 1
		lo := 0
		if !s.zeroOK[l] {
			lo = 1
		}
		// Build a mask of used digits from the current assignment.
		var used [10]bool
		for _, v := range res {
			if v >= 0 {
				used[v] = true
			}
		}
		for d := 9; d >= lo; d-- {
			if used[d] {
				continue
			}
			res[l] = d
			if s.solve(i-1, total, res) {
				return true
			}
		}
		res[l] = -1
		return false
	}

	t := s.targets[-p-1]
	sum := total
	for _, a := range s.colAdds[t.col] {
		sum += res[a]
	}
	if r := s.colRes[t.col]; r >= 0 {
		sum -= res[r]
	}
	if t.exp < 0 {
		return sum == 0
	}
	div := 1
	for e := 0; e < t.exp; e++ {
		div *= 10
	}
	if sum%div != 0 {
		return false
	}
	return s.solve(i-1, sum/div, res)
}

