package alphametics

import (
	"errors"
	"strings"
)

// Solve parses an alphametics puzzle of the form
// "WORD + WORD + ... == WORD" and returns the digit substitution
// that makes the equation valid, or an error if there is none.
func Solve(puzzle string) (map[string]int, error) {
	left, right, ok := strings.Cut(puzzle, "==")
	if !ok {
		return nil, errors.New("alphametics: invalid puzzle, missing \"==\"")
	}
	right = strings.TrimSpace(right)
	if right == "" || strings.ContainsAny(right, "+ ") {
		return nil, errors.New("alphametics: right side must be a single word")
	}
	var addends []string
	for _, f := range strings.FieldsFunc(left, func(r rune) bool {
		return r == '+' || r == ' '
	}) {
		if f != "" {
			addends = append(addends, f)
		}
	}
	if len(addends) == 0 {
		return nil, errors.New("alphametics: no addends")
	}
	words := append(append([]string{}, addends...), right)

	maxAddLen := 0
	for _, w := range addends {
		if len(w) > maxAddLen {
			maxAddLen = len(w)
		}
	}
	if len(right) > maxAddLen+1 {
		return nil, errors.New("alphametics: no solution possible")
	}

	// Collect letters; the leading letter of a multi-letter word may not
	// be zero.
	letterIdx := map[byte]int{}
	zeroOK := make([]bool, 0, 16)
	for n, w := range words {
		isResult := n == len(words)-1
		for k := 0; k < len(w); k++ {
			b := w[k]
			if _, ok := letterIdx[b]; ok {
				continue
			}
			if len(letterIdx) >= 10 {
				return nil, errors.New("alphametics: too many different letters")
			}
			letterIdx[b] = len(letterIdx)
			zeroOK = append(zeroOK, isResult || k > 0)
		}
	}

	// Group letter indexes per decimal column (0 = units).
	maxLen := 0
	for _, w := range words {
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}
	colAdds := make([][]int, maxLen)
	colRes := make([]int, maxLen)
	for i := range colRes {
		colRes[i] = -1
	}
	for n, w := range words {
		isResult := n == len(words)-1
		for k := 0; k < len(w); k++ {
			col := len(w) - 1 - k
			li := letterIdx[w[k]]
			if isResult {
				if colRes[col] < 0 {
					colRes[col] = li
				} else if colRes[col] != li {
					return nil, errors.New("alphametics: duplicated letter in column")
				}
			} else {
				colAdds[col] = append(colAdds[col], li)
			}
		}
	}

	// Build the ordered list of positions, processed back-to-front by the
	// search. Positions are encoded as:
	//   p > 0:  assign a digit to letter p-1
	//   p < 0:  target number -p-1
	//
	// For every column except the last, all newly appearing letters are
	// assigned as plain positions except one deferred letter; the target
	// closing a column assigns that deferred letter and verifies the
	// column constraint as soon as the column is complete. Columns whose
	// letters all appeared earlier emit a letterless target so their
	// constraint is never skipped. The list ends with the target closing
	// the last column.
	seen := make([]bool, len(letterIdx))
	var pos []int
	var targets []targetInfo

	for col := 0; col < maxLen-1; col++ {
		var slots []int
		for _, a := range colAdds[col] {
			slots = append(slots, a)
		}
		if colRes[col] >= 0 {
			slots = append(slots, colRes[col])
		}
		var free []int
		for _, sl := range slots {
			if !seen[sl] {
				free = append(free, sl)
			}
		}
		targetLetter := -1
		if r := colRes[col]; r >= 0 && !seen[r] {
			targetLetter = r
		} else if len(free) > 0 {
			targetLetter = free[0]
		}
		for _, sl := range free {
			if sl != targetLetter {
				pos = append(pos, sl+1)
				seen[sl] = true
			}
		}
		if targetLetter >= 0 {
			seen[targetLetter] = true
		}
		// The topmost target closes column maxLen-2 and must clear the
		// whole number, hence divisibility by 10^(maxLen-1); lower
		// targets only divide by 10.
		exp := 1
		if col == maxLen-2 {
			exp = maxLen - 1
		}
		targets = append(targets, targetInfo{col: col, exp: exp, letter: targetLetter})
		pos = append(pos, -1-len(targets))
	}
	// Final column: assign all its remaining letters, then close with a
	// target requiring the accumulated total to be exactly zero.
	lastCol := maxLen - 1
	for _, a := range colAdds[lastCol] {
		if !seen[a] {
			pos = append(pos, a+1)
			seen[a] = true
		}
	}
	if r := colRes[lastCol]; r >= 0 && !seen[r] {
		pos = append(pos, r+1)
		seen[r] = true
	}
	exp := -1
	if maxLen > 1 {
		// With a single column (maxLen == 1) the final target is also the
		// topmost one; requiring sum == 0 covers the 10^0 case.
		exp = -1
	}
	targets = append(targets, targetInfo{col: lastCol, exp: exp, letter: -1})
	pos = append(pos, -1-len(targets))

	s := &solver{
		zeroOK:  zeroOK,
		pos:     pos,
		colAdds: make([][]int32, maxLen),
		colRes:  make([]int32, maxLen),
		targets: targets,
	}
	for col := 0; col < maxLen; col++ {
		for _, a := range colAdds[col] {
			s.colAdds[col] = append(s.colAdds[col], int32(a))
		}
		s.colRes[col] = int32(colRes[col])
	}

	res := make([]int, len(letterIdx))
	for i := range res {
		res[i] = -1
	}
	if s.solve(len(pos)-1, 0, 0, res) {
		out := make(map[string]int, len(letterIdx))
		for b, i := range letterIdx {
			out[string(rune(b))] = res[i]
		}
		return out, nil
	}
	return nil, errors.New("alphametics: no solution")
}

type targetInfo struct {
	col    int
	exp    int // power of ten the running sum must be divisible by; -1 => sum must be 0
	letter int // deferred letter assigned at this target, or -1
}

type solver struct {
	zeroOK  []bool
	pos     []int
	colAdds [][]int32
	colRes  []int32
	targets []targetInfo
}

// solve walks the position list from its end to its start. total holds
// the carry/value contributed by the columns processed so far; at each
// target the column it closes is verified and the carry is propagated
// down to the next lower column.
func (s *solver) solve(i int, mask, total int, res []int) bool {
	p := s.pos[i]
	if p > 0 {
		return s.assign(i, mask, total, res, p-1, true)
	}
	t := s.targets[-p-1]
	if t.letter >= 0 {
		return s.assign(i, mask, total, res, t.letter, false)
	}
	return s.evalTarget(i, mask, total, res, t)
}

// assign tries every digit for letter l, then continues with the target
// check (when plain is false) or the remaining positions (plain true).
func (s *solver) assign(i, mask, total int, res []int, l int, plain bool) bool {
	lo := 0
	if !s.zeroOK[l] {
		lo = 1
	}
	for d := 9; d >= lo; d-- {
		if mask&(1<<d) != 0 {
			continue
		}
		res[l] = d
		var ok bool
		if plain {
			ok = s.solve(i-1, mask|(1<<d), total, res)
		} else {
			ok = s.evalTarget(i, mask|(1<<d), total, res, s.targets[-s.pos[i]-1])
		}
		if ok {
			return true
		}
	}
	res[l] = -1
	return false
}

func (s *solver) evalTarget(i, mask, total int, res []int, t targetInfo) bool {
	sum := total
	for _, a := range s.colAdds[t.col] {
		sum += res[a]
	}
	if r := s.colRes[t.col]; r >= 0 {
		sum -= res[r]
	}
	if t.exp < 0 {
		return sum == 0
	}
	div := 1
	for e := 0; e < t.exp; e++ {
		div *= 10
	}
	if sum%div != 0 {
		return false
	}
	return s.solve(i-1, mask, sum/div, res)
}
